      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the verification route, independent grounding requirement and availability qualifier."
    }
  },
  "signal_basis": {
    "component_id": "C015.signal_basis",
    "value": "Checks assess observers' direct access and copying, and seek independent agreement or disagreement about the same equipment, booking and handoff through available accounts or contemporaneous records.",
    "scope": "Event-specific verification; separate records or retrospective accounts may share origins, errors or narratives and therefore require independence assessment.",
