      "rationale": "These spans specify the checks, candidate sources, event alignment and limitations on treating sources as independent."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C015.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
